result.output:
340→		if strings.HasPrefix(key, sessionPath) {
341→			delete(entries, key)
342→		}
343→	}
344→
345→	// Write transcript
346→	if err := s.writeTranscript(ctx, opts, sessionPath, entries); err != nil {
347→		return filePaths, err
348→	}
349→	filePaths.Transcript = "/" + sessionPath + paths.TranscriptFileName
350→	filePaths.ContentHash = "/" + sessionPath + paths.ContentHashFileName
351→
352→	// Write prompts
353→	if len(opts.Prompts) > 0 {
354→		promptContent := redact.String(strings.Join(opts.Prompts, "\n\n---\n\n"))
355→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
356→		if err != nil {
357→			return filePaths, err
358→		}
359→		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
360→			Name: sessionPath + paths.PromptFileName,
361→			Mode: filemode.Regular,
362→			Hash: blobHash,
363→		}
364→		filePaths.Prompt = "/" + sessionPath + paths.PromptFileName
365→	}
366→
367→	// Write context
368→	if len(opts.Context) > 0 {
369→		blobHash, err := CreateBlobFromContent(s.repo, redact.Bytes(opts.Context))
370→		if err != nil {
371→			return filePaths, err
372→		}
373→		entries[sessionPath+paths.ContextFileName] = object.TreeEntry{
374→			Name: sessionPath + paths.ContextFileName,
375→			Mode: filemode.Regular,
376→			Hash: blobHash,
377→		}
378→		filePaths.Context = "/" + sessionPath + paths.ContextFileName
379→	}
380→
381→	// Write session-level metadata.json (CommittedMetadata with all fields including initial_attribution)
382→	sessionMetadata := CommittedMetadata{
383→		CheckpointID:                opts.CheckpointID,
384→		SessionID:                   opts.SessionID,
385→		Strategy:                    opts.Strategy,
386→		CreatedAt:                   time.Now().UTC(),
387→		Branch:                      opts.Branch,
388→		CheckpointsCount:            opts.CheckpointsCount,
389→		FilesTouched:                opts.FilesTouched,
390→		Agent:                       opts.Agent,
391→		TurnID:                      opts.TurnID,
392→		IsTask:                      opts.IsTask,
393→		ToolUseID:                   opts.ToolUseID,
394→		TranscriptIdentifierAtStart: opts.TranscriptIdentifierAtStart,
395→		CheckpointTranscriptStart:   opts.CheckpointTranscriptStart,
396→		TranscriptLinesAtStart:      opts.CheckpointTranscriptStart, // Deprecated: kept for backward compat
397→		TokenUsage:                  opts.TokenUsage,
398→		InitialAttribution:          opts.InitialAttribution,
399→		Summary:                     redactSummary(opts.Summary),
400→		CLIVersion:                  versioninfo.Version,
401→	}
402→
403→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(sessionMetadata, "", "  ")
404→	if err != nil {
405→		return filePaths, fmt.Errorf("failed to marshal session metadata: %w", err)
406→	}
407→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
408→	if err != nil {
409→		return filePaths, err
410→	}
411→	entries[sessionPath+paths.MetadataFileName] = object.TreeEntry{
412→		Name: sessionPath + paths.MetadataFileName,
413→		Mode: filemode.Regular,
414→		Hash: metadataHash,
415→	}
416→	filePaths.Metadata = "/" + sessionPath + paths.MetadataFileName
417→
418→	return filePaths, nil
419→}
