 27→// GetSessionInfo returns the current session info.
 28→func (s *ManualCommitStrategy) GetSessionInfo(ctx context.Context) (*SessionInfo, error) {
 29→	repo, err := OpenRepository(ctx)
 30→	if err != nil {
 31→		return nil, fmt.Errorf("failed to open git repository: %w", err)
 32→	}
 33→
 34→	// Check if we're on a shadow branch
 35→	head, err := repo.Head()
 36→	if err != nil {
 37→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
 38→	}
 39→
 40→	if head.Name().IsBranch() {
 41→		branchName := head.Name().Short()
 42→		if strings.HasPrefix(branchName, shadowBranchPrefix) {
 43→			return nil, ErrNoSession
 44→		}
 45→	}
 46→
 47→	// Find sessions for current HEAD
 48→	sessions, err := s.findSessionsForCommit(ctx, head.Hash().String())
 49→	if err != nil || len(sessions) == 0 {
 50→		return nil, ErrNoSession
 51→	}
 52→
 53→	// Return info for most recent session
 54→	state := sessions[0]
 55→	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
 56→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
 57→
 58→	info := &SessionInfo{
 59→		SessionID: state.SessionID,
 60→		Reference: shadowBranchName,
 61→	}
 62→
 63→	if ref, err := repo.Reference(refName, true); err == nil {
 64→		info.CommitHash = ref.Hash().String()
 65→	}
 66→
 67→	return info, nil
 68→}
