 99→// GetSessionContext returns the context.md content for a session.
100→// For manual-commit strategy, reads from the entire/checkpoints/v1 branch using the sessions map.
101→func (s *ManualCommitStrategy) GetSessionContext(ctx context.Context, sessionID string) string {
102→	// Find a checkpoint for this session
103→	checkpoints, err := s.getCheckpointsForSession(ctx, sessionID)
104→	if err != nil || len(checkpoints) == 0 {
105→		return ""
106→	}
107→
108→	// Use the most recent checkpoint
109→	sort.Slice(checkpoints, func(i, j int) bool {
110→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
111→	})
112→	checkpointID := checkpoints[0].CheckpointID
113→
114→	repo, err := OpenRepository(ctx)
115→	if err != nil {
116→		return ""
117→	}
118→
119→	// Get the sessions branch
120→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
121→	ref, err := repo.Reference(refName, true)
122→	if err != nil {
123→		return ""
124→	}
125→
126→	commit, err := repo.CommitObject(ref.Hash())
127→	if err != nil {
128→		return ""
129→	}
130→
131→	tree, err := commit.Tree()
132→	if err != nil {
133→		return ""
134→	}
135→
136→	// Get checkpoint tree to read the sessions summary
137→	checkpointTree, err := tree.Tree(checkpointID.Path())
138→	if err != nil {
139→		return ""
140→	}
141→
142→	// Read root metadata to find session's context path from sessions map
143→	metadataFile, err := checkpointTree.File(paths.MetadataFileName)
144→	if err != nil {
145→		return ""
146→	}
147→
148→	metadataContent, err := metadataFile.Contents()
149→	if err != nil {
150→		return ""
151→	}
152→
153→	var summary checkpoint.CheckpointSummary
154→	if err := json.Unmarshal([]byte(metadataContent), &summary); err != nil {
155→		return ""
156→	}
157→
158→	// Look up context path from sessions array
159→	// Try to find the session by reading each session's metadata, or fall back to latest
160→	var sessionPaths checkpoint.SessionFilePaths
161→	if len(summary.Sessions) > 0 {
162→		// Use the latest session by default (last entry in the array)
163→		latestIndex := len(summary.Sessions) - 1
164→		sessionPaths = summary.Sessions[latestIndex]
165→	} else {
166→		return ""
167→	}
168→
169→	// Read context using absolute path from root tree
170→	// SessionFilePaths now contains absolute paths like "/a1/b2c3d4e5f6/1/context.md"
171→	if sessionPaths.Context == "" {
172→		return ""
173→	}
174→	// Strip leading "/" for tree.File() which expects paths without leading slash
175→	contextPath := strings.TrimPrefix(sessionPaths.Context, "/")
176→	file, err := tree.File(contextPath)
177→	if err != nil {
178→		return ""
179→	}
180→	content, err := file.Contents()
181→	if err != nil {
182→		return ""
183→	}
184→	return content
185→}
