1255→// getSessionDescriptionFromTree reads the first line of prompt.txt or context.md from a git tree.
1256→// This is the tree-based equivalent of getSessionDescription (which reads from filesystem).
1257→//
1258→// If metadataDir is provided, looks for files at metadataDir/prompt.txt or metadataDir/context.md.
1259→// If metadataDir is empty, first tries the root of the tree (for when the tree is already
1260→// the session directory), then falls back to
1261→// searching for .entire/metadata/*/prompt.txt or context.md (for full worktree trees).
1262→func getSessionDescriptionFromTree(tree *object.Tree, metadataDir string) string {
1263→	// Helper to read first line from a file in tree
1264→	readFirstLine := func(path string) string {
1265→		file, err := tree.File(path)
1266→		if err != nil {
1267→			return ""
1268→		}
1269→		content, err := file.Contents()
1270→		if err != nil {
1271→			return ""
1272→		}
1273→		lines := strings.SplitN(content, "\n", 2)
1274→		if len(lines) > 0 && lines[0] != "" {
1275→			desc := strings.TrimSpace(lines[0])
1276→			// Remove markdown header prefix if present
1277→			return strings.TrimPrefix(desc, "# ")
1278→		}
1279→		return ""
1280→	}
1281→
1282→	// If metadataDir is provided, look there directly
1283→	if metadataDir != "" {
1284→		if desc := readFirstLine(metadataDir + "/" + paths.PromptFileName); desc != "" {
1285→			return desc
1286→		}
1287→		if desc := readFirstLine(metadataDir + "/" + paths.ContextFileName); desc != "" {
1288→			return desc
1289→		}
1290→		return NoDescription
1291→	}
1292→
1293→	// No metadataDir provided - first try looking at the root of the tree
1294→	// (used when the tree is already the session directory)
1295→	if desc := readFirstLine(paths.PromptFileName); desc != "" {
1296→		return desc
1297→	}
1298→	if desc := readFirstLine(paths.ContextFileName); desc != "" {
1299→		return desc
1300→	}
1301→
1302→	// Fall back to searching for .entire/metadata/*/prompt.txt or context.md
1303→	// (used when the tree is the full worktree)
1304→	var desc string
1305→	//nolint:errcheck // We ignore errors here as we're just searching for a description
1306→	_ = tree.Files().ForEach(func(f *object.File) error {
1307→		if desc != "" {
1308→			return nil // Already found description
1309→		}
1310→		name := f.Name
1311→		if strings.Contains(name, ".entire/metadata/") {
1312→			if strings.HasSuffix(name, "/"+paths.PromptFileName) || strings.HasSuffix(name, "/"+paths.ContextFileName) {
1313→				content, err := f.Contents()
1314→				if err != nil {
1315→					return nil //nolint:nilerr // Skip files we can't read, continue searching
1316→				}
1317→				lines := strings.SplitN(content, "\n", 2)
1318→				if len(lines) > 0 && lines[0] != "" {
1319→					desc = strings.TrimSpace(lines[0])
1320→					desc = strings.TrimPrefix(desc, "# ")
1321→				}
1322→			}
1323→		}
1324→		return nil
1325→	})
1326→
1327→	if desc != "" {
1328→		return desc
1329→	}
1330→	return NoDescription
1331→}
