1133→func (s *GitStore) UpdateCommitted(ctx context.Context, opts UpdateCommittedOptions) error {
1134→	if opts.CheckpointID.IsEmpty() {
1135→		return errors.New("invalid update options: checkpoint ID is required")
1136→	}
1137→
1138→	// Ensure sessions branch exists
1139→	if err := s.ensureSessionsBranch(); err != nil {
1140→		return fmt.Errorf("failed to ensure sessions branch: %w", err)
1141→	}
1142→
1143→	// Get branch ref and root tree hash (O(1), no flatten)
1144→	parentHash, rootTreeHash, err := s.getSessionsBranchRef()
1145→	if err != nil {
1146→		return err
1147→	}
1148→
1149→	// Flatten only the checkpoint subtree
1150→	basePath := opts.CheckpointID.Path() + "/"
1151→	checkpointPath := opts.CheckpointID.Path()
1152→	entries, err := s.flattenCheckpointEntries(rootTreeHash, checkpointPath)
1153→	if err != nil {
1154→		return err
1155→	}
1156→
1157→	// Read root CheckpointSummary to find the session slot
1158→	rootMetadataPath := basePath + paths.MetadataFileName
1159→	entry, exists := entries[rootMetadataPath]
1160→	if !exists {
1161→		return ErrCheckpointNotFound
1162→	}
1163→
1164→	checkpointSummary, err := s.readSummaryFromBlob(entry.Hash)
1165→	if err != nil {
1166→		return fmt.Errorf("failed to read checkpoint summary: %w", err)
1167→	}
1168→	if len(checkpointSummary.Sessions) == 0 {
1169→		return ErrCheckpointNotFound
1170→	}
1171→
1172→	// Find session index matching opts.SessionID
1173→	sessionIndex := -1
1174→	for i := range len(checkpointSummary.Sessions) {
1175→		metaPath := fmt.Sprintf("%s%d/%s", basePath, i, paths.MetadataFileName)
1176→		if metaEntry, metaExists := entries[metaPath]; metaExists {
1177→			meta, metaErr := s.readMetadataFromBlob(metaEntry.Hash)
1178→			if metaErr == nil && meta.SessionID == opts.SessionID {
1179→				sessionIndex = i
1180→				break
1181→			}
1182→		}
1183→	}
1184→	if sessionIndex == -1 {
1185→		// Fall back to latest session; log so mismatches are diagnosable.
1186→		sessionIndex = len(checkpointSummary.Sessions) - 1
1187→		logging.Debug(ctx, "UpdateCommitted: session ID not found, falling back to latest",
1188→			slog.String("session_id", opts.SessionID),
1189→			slog.String("checkpoint_id", string(opts.CheckpointID)),
1190→			slog.Int("fallback_index", sessionIndex),
1191→		)
1192→	}
1193→
1194→	sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
1195→
1196→	// Replace transcript (full replace, not append)
1197→	// Apply redaction as safety net (caller should redact, but we ensure it here)
1198→	if len(opts.Transcript) > 0 {
1199→		transcript, err := redact.JSONLBytes(opts.Transcript)
1200→		if err != nil {
1201→			return fmt.Errorf("failed to redact transcript secrets: %w", err)
1202→		}
1203→		if err := s.replaceTranscript(ctx, transcript, opts.Agent, sessionPath, entries); err != nil {
1204→			return fmt.Errorf("failed to replace transcript: %w", err)
1205→		}
1206→	}
1207→
1208→	// Replace prompts (apply redaction as safety net)
1209→	if len(opts.Prompts) > 0 {
1210→		promptContent := redact.String(strings.Join(opts.Prompts, "\n\n---\n\n"))
1211→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
1212→		if err != nil {
1213→			return fmt.Errorf("failed to create prompt blob: %w", err)
1214→		}
1215→		entries[sessionPath+paths.PromptFileName] = object.TreeEntry{
1216→			Name: sessionPath + paths.PromptFileName,
1217→			Mode: filemode.Regular,
1218→			Hash: blobHash,
1219→		}
1220→	}
1221→
1222→	// Replace context (apply redaction as safety net)
1223→	if len(opts.Context) > 0 {
1224→		contextBlob, err := CreateBlobFromContent(s.repo, redact.Bytes(opts.Context))
1225→		if err != nil {
1226→			return fmt.Errorf("failed to create context blob: %w", err)
1227→		}
1228→		entries[sessionPath+paths.ContextFileName] = object.TreeEntry{
1229→			Name: sessionPath + paths.ContextFileName,
1230→			Mode: filemode.Regular,
1231→			Hash: contextBlob,
1232→		}
1233→	}
1234→
1235→	// Build checkpoint subtree and splice into root (O(depth) tree surgery)
1236→	newTreeHash, err := s.spliceCheckpointSubtree(rootTreeHash, opts.CheckpointID, basePath, entries)
1237→	if err != nil {
1238→		return err
1239→	}
1240→
1241→	authorName, authorEmail := GetGitAuthorFromRepo(s.repo)
1242→	commitMsg := fmt.Sprintf("Finalize transcript for Checkpoint: %s", opts.CheckpointID)
1243→	newCommitHash, err := s.createCommit(newTreeHash, parentHash, commitMsg, authorName, authorEmail)
1244→	if err != nil {
1245→		return err
1246→	}
1247→
1248→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1249→	newRef := plumbing.NewHashReference(refName, newCommitHash)
1250→	if err := s.repo.Storer.SetReference(newRef); err != nil {
1251→		return fmt.Errorf("failed to set branch reference: %w", err)
1252→	}
1253→
1254→	return nil
1255→}
