1257→// replaceTranscript writes the full transcript content, replacing any existing transcript.
1258→// Also removes any chunk files from a previous write and updates the content hash.
1259→func (s *GitStore) replaceTranscript(ctx context.Context, transcript []byte, agentType types.AgentType, sessionPath string, entries map[string]object.TreeEntry) error {
1260→	// Remove existing transcript files (base + any chunks)
1261→	transcriptBase := sessionPath + paths.TranscriptFileName
1262→	for key := range entries {
1263→		if key == transcriptBase || strings.HasPrefix(key, transcriptBase+".") {
1264→			delete(entries, key)
1265→		}
